import{_ as t,o,c as d,a3 as a}from"./chunks/framework.B8jMSdkO.js";const k=JSON.parse('{"title":"Check the docs contract","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/check-docs.md","filePath":"how-to/check-docs.md"}'),c={name:"how-to/check-docs.md"};function s(i,e,r,n,h,l){return o(),d("div",null,[...e[0]||(e[0]=[a(`<h1 id="check-the-docs-contract" tabindex="-1">Check the docs contract <a class="header-anchor" href="#check-the-docs-contract" aria-label="Permalink to &quot;Check the docs contract&quot;">​</a></h1><p><code>cypera check</code> verifies that a repo&#39;s documentation meets the org contract — the same rules every sibling repo is held to. It is the gate <code>docs:check</code> scripts run in CI.</p><h2 id="run-it" tabindex="-1">Run it <a class="header-anchor" href="#run-it" aria-label="Permalink to &quot;Run it&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cypera</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --repo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/repo</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # text report</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cypera</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --repo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/repo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # machine-readable</span></span></code></pre></div><p>Exit status is non-zero when any rule fails; <code>SKIP</code> never fails.</p><h2 id="the-rules" tabindex="-1">The rules <a class="header-anchor" href="#the-rules" aria-label="Permalink to &quot;The rules&quot;">​</a></h2><table tabindex="0"><thead><tr><th>rule</th><th>what it checks</th></tr></thead><tbody><tr><td><code>readme</code></td><td><code>README.md</code> exists, is under 200 lines, has what/why/quickstart-shaped content, and contains an install or run command.</td></tr><tr><td><code>agents-md</code></td><td><code>AGENTS.md</code> exists with Layout-, Commands-, and Boundary-ish sections.</td></tr><tr><td><code>no-changelog</code></td><td>No <code>CHANGELOG*</code> at the repo root — releases are tarsi&#39;s job.</td></tr><tr><td><code>no-version-in-prose</code></td><td>No <code>v?\\d+\\.\\d+\\.\\d+</code> in prose (<code>.md</code>/<code>.txt</code>); manifests and lockfiles are exempt, as are fenced code blocks, inline code spans, and raw HTML <code>&lt;script&gt;</code>/<code>&lt;style&gt;</code> blocks.</td></tr><tr><td><code>docs-site</code></td><td>A <code>docs/</code> worktree (or equivalent) with the four Diátaxis quadrants: <code>tutorials/</code>, <code>how-to/</code>, <code>reference/</code>, <code>explanation/</code>.</td></tr><tr><td><code>docs-check-script</code></td><td><code>docs/package.json</code> has a <code>docs:check</code> script.</td></tr><tr><td><code>generated-fresh</code></td><td>Every output declared in <code>cypera.toml</code> regenerates byte-identically — cypera rebuilds each page in memory and diffs (no writes). Without <code>cypera.toml</code> the rule skips.</td></tr></tbody></table><p>Profile-driven rules (gated by <code>[check] profile</code> in <code>cypera.toml</code>; all SKIP without one, and when the <code>docs/</code> worktree is absent):</p><table tabindex="0"><thead><tr><th>rule</th><th>what it checks</th></tr></thead><tbody><tr><td><code>content-pages</code></td><td>The required docs tree per profile — <code>engine</code>: all four Diátaxis quadrant dirs, ≥1 tutorial, ≥3 how-tos, and <code>explanation/{architecture,concepts,boundaries,decisions}.md</code>; <code>library</code>: <code>index.md</code> + <code>explanation/{architecture,concepts}.md</code>; <code>content</code>: exempt.</td></tr><tr><td><code>tutorial-count</code></td><td><code>docs/tutorials/</code> holds exactly one markdown file for <code>engine</code> (the single golden path), at most one for <code>library</code>; <code>content</code> exempt.</td></tr><tr><td><code>tutorial-name</code></td><td>The canonical tutorial filename is <code>docs/tutorials/getting-started.md</code> — <code>engine</code> FAILs when <code>tutorials/</code> has markdown but none is <code>getting-started.md</code>; <code>library</code>/<code>content</code> SKIP (engine-only contract).</td></tr><tr><td><code>index-router</code></td><td><code>docs/index.md</code> links to at least 3 of the 4 quadrant dirs, routing each reader journey.</td></tr><tr><td><code>no-orphan-getting-started</code></td><td>No <code>getting-started.md</code> at the <code>docs/</code> root — the golden path lives in <code>docs/tutorials/</code>.</td></tr></tbody></table><p>Every finding carries <code>file:line</code> evidence where applicable.</p><p>A repo that legitimately can&#39;t satisfy a rule — a content-only ledger mount, a theme package, the website repo itself — exempts it with <code>[check] skip = [&quot;docs-site&quot;, ...]</code> in <code>cypera.toml</code> (see <a href="/cypera/reference/cypera-toml.html">the schema</a>). Exempt rules still run and report <code>SKIP</code>, which never fails the check; unknown names warn on stderr.</p><h2 id="wire-it-into-a-repo" tabindex="-1">Wire it into a repo <a class="header-anchor" href="#wire-it-into-a-repo" aria-label="Permalink to &quot;Wire it into a repo&quot;">​</a></h2><ol><li><p>Add <code>cypera.toml</code> (see <a href="/cypera/reference/cypera-toml.html">the schema</a>).</p></li><li><p>Add the script to <code>docs/package.json</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;docs:check&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;cargo run -q --manifest-path ../cypera/Cargo.toml -p cypera -- check --repo ..&quot;</span></span></code></pre></div></li><li><p>Run <code>cypera gen …</code> once so the declared outputs exist, then <code>cypera check --repo .</code> stays green as long as they stay fresh.</p></li></ol>`,13)])])}const u=t(c,[["render",s]]);export{k as __pageData,u as default};
